#!/usr/bin/env node
// Zero-dependency CSV summarizer: sums `amount` grouped by `category` plus a grand total.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const inputPath = path.resolve(root, process.argv[2] ?? 'uploads/sample.csv');
const outputPath = path.resolve(root, process.argv[3] ?? 'outputs/result.json');

const raw = await readFile(inputPath, 'utf8');
const lines = raw
  .split(/\r?\n/)
  .map((line) => line.trim())
  .filter((line) => line.length > 0);

if (lines.length === 0) throw new Error(`empty CSV: ${inputPath}`);

const header = lines[0].split(',').map((name) => name.trim());
const categoryIndex = header.indexOf('category');
const amountIndex = header.indexOf('amount');
if (categoryIndex === -1 || amountIndex === -1) {
  throw new Error(`CSV must have "category" and "amount" columns, got: ${header.join(',')}`);
}

const byCategory = {};
let total = 0;

for (const line of lines.slice(1)) {
  const cells = line.split(',');
  const category = (cells[categoryIndex] ?? '').trim();
  const amount = Number((cells[amountIndex] ?? '').trim());
  if (!category) continue;
  if (!Number.isFinite(amount)) throw new Error(`invalid amount in line: ${line}`);
  byCategory[category] = (byCategory[category] ?? 0) + amount;
  total += amount;
}

// Round away float noise (e.g. 0.1 + 0.2) before serializing.
for (const key of Object.keys(byCategory)) byCategory[key] = Number(byCategory[key].toFixed(10));
total = Number(total.toFixed(10));

const result = { byCategory, total };
await writeFile(outputPath, `${JSON.stringify(result, null, 2)}\n`, 'utf8');
console.log(JSON.stringify(result, null, 2));
